package local.civic.home;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.drawable.Drawable;import android.view.*;import android.widget.*;import java.util.*;
public final class HiddenAppsActivity extends Activity {
 UiKit ui;SharedPreferences prefs;Set<String> hidden;final ArrayList<ResolveInfo> apps=new ArrayList<>();final HashMap<String,String> labels=new HashMap<>();final HashMap<String,Drawable> icons=new HashMap<>();BaseAdapter adapter;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(ThemeTokens.get(this).background));getWindow().getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);ui=new UiKit(this);prefs=getSharedPreferences("home",0);hidden=new HashSet<>(prefs.getStringSet("hidden_apps",Collections.emptySet()));LinearLayout root=ui.column();root.setBackgroundColor(ui.t.background);root.addView(ui.header("Hidden apps"),new LinearLayout.LayoutParams(-1,ui.dp(56)));TextView show=ui.text("Show all",16,ui.t.accent);show.setGravity(Gravity.CENTER);show.setMinHeight(ui.dp(56));show.setOnClickListener(v->{hidden.clear();save();adapter.notifyDataSetChanged();});root.addView(show);ListView list=new ListView(this);list.setDivider(null);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);adapter=new BaseAdapter(){public int getCount(){return apps.size();}public Object getItem(int n){return apps.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){LinearLayout row;if(old instanceof LinearLayout)row=(LinearLayout)old;else{row=new LinearLayout(HiddenAppsActivity.this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(ui.dp(16),0,ui.dp(16),0);row.setMinimumHeight(ui.dp(56));ImageView image=new ImageView(HiddenAppsActivity.this);image.setId(android.R.id.icon);row.addView(image,new LinearLayout.LayoutParams(ui.dp(40),ui.dp(40)));TextView name=ui.text("",16,ui.t.textPrimary);name.setId(android.R.id.text1);name.setPadding(ui.dp(12),0,0,0);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));CheckBox check=new CheckBox(HiddenAppsActivity.this);check.setId(android.R.id.checkbox);check.setClickable(false);check.setFocusable(false);check.setButtonTintList(android.content.res.ColorStateList.valueOf(ui.t.accent));row.addView(check,new LinearLayout.LayoutParams(ui.dp(56),ui.dp(56)));}ResolveInfo info=apps.get(n);String pkg=info.activityInfo.packageName;((ImageView)row.findViewById(android.R.id.icon)).setImageDrawable(icons.get(pkg));((TextView)row.findViewById(android.R.id.text1)).setText(labels.get(pkg));((CheckBox)row.findViewById(android.R.id.checkbox)).setChecked(hidden.contains(pkg));return row;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,n,id)->{String pkg=apps.get(n).activityInfo.packageName;if(!hidden.remove(pkg))hidden.add(pkg);save();adapter.notifyDataSetChanged();});new Thread(()->{PackageManager pm=getPackageManager();List<ResolveInfo> all=pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);Collections.sort(all,new ResolveInfo.DisplayNameComparator(pm));ArrayList<ResolveInfo> found=new ArrayList<>();HashMap<String,Drawable> loaded=new HashMap<>();HashMap<String,String> loadedLabels=new HashMap<>();for(ResolveInfo r:all){String pkg=r.activityInfo.packageName;if(pkg.equals(getPackageName())||loaded.containsKey(pkg))continue;found.add(r);loadedLabels.put(pkg,r.loadLabel(pm).toString());try{loaded.put(pkg,r.loadIcon(pm));}catch(RuntimeException ignored){loaded.put(pkg,null);}}runOnUiThread(()->{if(isFinishing()||isDestroyed())return;apps.addAll(found);icons.putAll(loaded);labels.putAll(loadedLabels);adapter.notifyDataSetChanged();});}).start();}
 void save(){prefs.edit().putStringSet("hidden_apps",new HashSet<>(hidden)).apply();}
}
